# Constants
REPLACE_NONE = "None"
def task_func(json_str):
    data = json.loads(json_str)

    def remove_none_and_replace_email(obj):
        if isinstance(obj, dict):
            return {k: remove_none_and_replace_email(v) for k, v in obj.items() if v is not None}
        elif isinstance(obj, list):
            return [remove_none_and_replace_email(item) for item in obj if item is not None]
        elif isinstance(obj, str) and re.match(r'^[\w\.-]+@[\w\.-]+\.\w+$', obj):
            return REPLACE_NONE
        else:
            return obj

    processed_data = remove_none_and_replace_email(data)

    def collect_all_values(obj, values):
        if isinstance(obj, dict):
            for v in obj.values():
                collect_all_values(v, values)
        elif isinstance(obj, list):
            for item in obj:
                collect_all_values(item, values)
        else:
            values.append(obj)

    all_values = []
    collect_all_values(processed_data, all_values)
    value_counts = Counter(all_values)

    return {"data": processed_data, "value_counts": value_counts}

